#!/usr/bin/env python3
"""Bounded ordinary exhaustive unsigned <=64-bit enum differential."""
import argparse,json,tempfile
from dataclasses import dataclass
from pathlib import Path
from compiler_process import run_compiler
from diff_thin_pointer_casts import primary_error
SZC_MODE='emit-qbe'
@dataclass
class Case:
 label:str
 source:str
 lane:str='positive'
def program(prefix,body):return prefix+'pub fn main()void{'+body+'}\n'
def check(c):return 'const check:u8=if('+c+')0 else 256;_=check;'
def cases():
 yield Case('inferred-2',program('const E=enum{f0,f1,};',''+check('@TypeOf(@intFromEnum(E.f1))==u1 and @intFromEnum(E.f1)==1')),'positive')
 yield Case('inferred-3',program('const E=enum{f0,f1,f2,};',''+check('@TypeOf(@intFromEnum(E.f2))==u2 and @intFromEnum(E.f2)==2')),'positive')
 yield Case('inferred-5',program('const E=enum{f0,f1,f2,f3,f4,};',''+check('@TypeOf(@intFromEnum(E.f4))==u3 and @intFromEnum(E.f4)==4')),'positive')
 yield Case('inferred-9',program('const E=enum{f0,f1,f2,f3,f4,f5,f6,f7,f8,};',''+check('@TypeOf(@intFromEnum(E.f8))==u4 and @intFromEnum(E.f8)==8')),'positive')
 yield Case('unsigned-u1',program('const E=enum(u1){lo=0,hi=1,};',''+check('@TypeOf(@intFromEnum(E.hi))==u1 and @intFromEnum(E.hi)==1 and @sizeOf(E)==1 and @alignOf(E)==1 and @bitSizeOf(E)==1')),'positive')
 yield Case('unsigned-u8',program('const E=enum(u8){lo=0,hi=255,};',''+check('@TypeOf(@intFromEnum(E.hi))==u8 and @intFromEnum(E.hi)==255 and @sizeOf(E)==1 and @alignOf(E)==1 and @bitSizeOf(E)==8')),'positive')
 yield Case('unsigned-u9',program('const E=enum(u9){lo=0,hi=511,};',''+check('@TypeOf(@intFromEnum(E.hi))==u9 and @intFromEnum(E.hi)==511 and @sizeOf(E)==2 and @alignOf(E)==2 and @bitSizeOf(E)==9')),'positive')
 yield Case('unsigned-u16',program('const E=enum(u16){lo=0,hi=65535,};',''+check('@TypeOf(@intFromEnum(E.hi))==u16 and @intFromEnum(E.hi)==65535 and @sizeOf(E)==2 and @alignOf(E)==2 and @bitSizeOf(E)==16')),'positive')
 yield Case('unsigned-u33',program('const E=enum(u33){lo=0,hi=8589934591,};',''+check('@TypeOf(@intFromEnum(E.hi))==u33 and @intFromEnum(E.hi)==8589934591 and @sizeOf(E)==8 and @alignOf(E)==8 and @bitSizeOf(E)==33')),'positive')
 yield Case('unsigned-u64',program('const E=enum(u64){lo=0,hi=18446744073709551615,};',''+check('@TypeOf(@intFromEnum(E.hi))==u64 and @intFromEnum(E.hi)==18446744073709551615 and @sizeOf(E)==8 and @alignOf(E)==8 and @bitSizeOf(E)==64')),'positive')
 yield Case('tag-order',program('const E=enum(u8){a=7,b,c=2,d,};',''+check('@intFromEnum(E.a)==7 and @intFromEnum(E.b)==8 and @intFromEnum(E.c)==2 and @intFromEnum(E.d)==3')),'positive')
 yield Case('implicit-first',program('const E=enum(u8){a,b=7,c,};',''+check('@intFromEnum(E.a)==0 and @intFromEnum(E.c)==8')),'positive')
 yield Case('tag-expression',program('const base:u8=4;const E=enum(u8){a=base+1,b=@as(u8,9),c,};',''+check('@intFromEnum(E.a)==5 and @intFromEnum(E.c)==10')),'positive')
 yield Case('namespace-tag-expression',program('const E=enum(u8){a=base,b,pub const base:u8=7;};',''+check('@intFromEnum(E.a)==7 and @intFromEnum(E.b)==8')),'positive')
 yield Case('type-alias',program('const E=enum(u8){a=1,b=7,c=250,};const Alias=E;','const e:Alias=.b;'+check('e==E.b and Alias==E')),'positive')
 yield Case('namespace-alias',program('const E=enum(u8){a=1,b=7,c=250,};const H=struct{pub const Alias=E;};','const e:H.Alias=.c;'+check('e==E.c')),'positive')
 yield Case('quoted-field',program('const E=enum(u8){@"a b"=1,@"re\\x61d"=7,};',''+check('@intFromEnum(@field(E,"a b"))==1 and E.read==E.@"re\\x61d"')),'positive')
 yield Case('namespace-reflection',program('const E=enum{a,b,pub const answer:u8=9;pub const alias:E=.b;};',''+check('@hasField(E,"a") and !@hasDecl(E,"a") and @hasDecl(E,"answer") and !@hasField(E,"answer") and E.alias==E.b')),'positive')
 yield Case('namespace-function',program('const E=enum(u8){a=7,b,fn get(e:E)u8{return @intFromEnum(e);}};','_=E.get(.a);'),'positive')
 yield Case('literal-as',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@as(E,.b);'+check('e==E.b')),'positive')
 yield Case('literal-assignment',program('const E=enum(u8){a=1,b=7,c=250,};','var e:E=.a;e=.c;_= &e;'),'positive')
 yield Case('known-conversion',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@enumFromInt(7);'+check('e==E.b and @intFromEnum(e)==7')),'positive')
 yield Case('known-conversion-typed',program('const E=enum(u8){a=1,b=7,c=250,};','const n:u16=250;const e:E=@enumFromInt(n);'+check('e==E.c')),'positive')
 yield Case('known-conversion-max64',program('const E=enum(u64){lo=1,hi=18446744073709551615,};','const e:E=@enumFromInt(18446744073709551615);'+check('e==E.hi')),'positive')
 yield Case('known-singleton',program('const E=enum{only,};','const e:E=.only;'+check('e==E.only and @TypeOf(@intFromEnum(e))==u0 and @intFromEnum(e)==0 and @sizeOf(E)==0 and @alignOf(E)==1 and @bitSizeOf(E)==0')),'positive')
 yield Case('known-explicit-u0',program('const E=enum(u0){only=0,};','const e:E=@enumFromInt(0);'+check('e==E.only and @sizeOf(E)==0')),'positive')
 yield Case('empty-pointer-lazy',program('const E=enum{};',''+check('@sizeOf(*const E)==@sizeOf(usize)')),'positive')
 yield Case('unused-invalid-tag',program('const E=enum(u8){a=256,b,};',''),'positive')
 yield Case('invalid-pointer-lazy',program('const E=enum(u8){a=256,b,};',''+check('@sizeOf(*const E)==@sizeOf(usize)')),'positive')
 yield Case('runtime-decode',program('const E=enum(u8){a=1,b=7,c=250,};fn f(n:u16)E{return @enumFromInt(n);}','_=f(7);'),'positive')
 yield Case('runtime-encode',program('const E=enum(u8){a=1,b=7,c=250,};fn f(e:E)u8{return @intFromEnum(e);}','_=f(.b);'),'positive')
 yield Case('internal-direct',program('const E=enum(u8){a=1,b=7,c=250,};fn f(e:E)E{return e;}','_=f(.c);'),'positive')
 yield Case('internal-indirect',program('const E=enum(u8){a=1,b=7,c=250,};fn f(e:E)E{return e;}fn call(p:*const fn(E)E,e:E)E{return p(e);}','_=call(&f,.c);'),'positive')
 yield Case('struct-default',program('const E=enum(u8){a=1,b=7,c=250,};const H=struct{e:E=.b,};','const h:H=.{};'+check('h.e==E.b')),'positive')
 yield Case('nested-default',program('const E=enum(u8){a=1,b=7,c=250,};const I=struct{e:E=.c,};const O=struct{i:I=.{},};','const o:O=.{};'+check('o.i.e==E.c')),'positive')
 yield Case('runtime-struct-field',program('const E=enum(u8){a=1,b=7,c=250,};const H=struct{e:E=.a,};fn f(n:u8)H{return .{.e=@enumFromInt(n)};}','var h=f(7);h.e=.c;_= &h;'),'positive')
 yield Case('aggregate-ABI',program('const E=enum(u8){a=1,b=7,c=250,};const H=struct{e:E,n:u8,};fn f(h:H)H{return h;}','_=f(.{.e=.b,.n=3});'),'positive')
 yield Case('array-storage',program('const E=enum(u8){a=1,b=7,c=250,};fn index()usize{return 1;}','var a:[2]E=.{.a,.b};a[index()]=.c;_= &a;'),'positive')
 yield Case('slice-storage',program('const E=enum(u8){a=1,b=7,c=250,};fn f(s:[]E)void{s[1]=.c;}','var a:[2]E=.{.a,.b};f(&a);'),'positive')
 yield Case('global-scalar',program('const E=enum(u8){a=1,b=7,c=250,};var g:E=.a;','g=.b;_=g;'),'positive')
 yield Case('global-struct-array',program('const E=enum(u8){a=1,b=7,c=250,};const H=struct{e:E=.b,};var g:[2]H=.{.{},.{.e=.c}};','g[0].e=.a;_=g[1];'),'positive')
 yield Case('global-pointer',program('const E=enum(u8){a=1,b=7,c=250,};var g:E=.a;const p:*E=&g;','p.*=.c;'),'positive')
 yield Case('static-pointer',program('const E=enum(u8){a=1,b=7,c=250,};const e:E=.b;fn f(p:*const E)E{return p.*;}','_=f(&e);'),'positive')
 yield Case('pointer-qualifiers',program('const E=enum(u8){a=1,b=7,c=250,};fn f(p:*volatile E)u8{return @intFromEnum(p.*);}','var e:E=.a;_=f(&e);'),'positive')
 yield Case('enum-pointer-identity',program('const E=enum(u8){a=1,b=7,c=250,};','var e:E=.a;const p:*E=&e;const q:*const E=p;_=p==q;'),'positive')
 yield Case('branch-result',program('const E=enum(u8){a=1,b=7,c=250,};fn f(b:bool)E{return if(b).a else .b;}','_=f(true);'),'positive')
 yield Case('block-result',program('const E=enum(u8){a=1,b=7,c=250,};fn f(b:bool)E{return blk:{if(b)break :blk .c;break :blk .a;};}','_=f(false);'),'positive')
 yield Case('u9-runtime',program('const E=enum(u9){a=1,b=257,c=511,};fn f(n:u16)u9{const e:E=@enumFromInt(n);return @intFromEnum(e);}','_=f(257);'),'positive')
 yield Case('u33-runtime',program('const E=enum(u33){a=1,b=4294967297,c=8589934591,};fn f(n:u64)u33{const e:E=@enumFromInt(n);return @intFromEnum(e);}','_=f(4294967297);'),'positive')
 yield Case('u64-runtime',program('const E=enum(u64){a=1,b=9223372036854775808,c=18446744073709551615,};fn f(n:u64)u64{const e:E=@enumFromInt(n);return @intFromEnum(e);}','_=f(18446744073709551615);'),'positive')
 yield Case('callback-liveness',program('const E=enum(u8){a=1,b=7,c=250,};fn f(e:E)E{return e;}const H=struct{cb:*const fn(E)E=&f,};','const h:H=.{};_=h.cb(.b);'),'positive')
 yield Case('error/nominal',program('const E=enum{a,b,};const F=enum{a,b,};','const e:E=F.a;_=e;'),'error')
 yield Case('error/integer-to-enum',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=7;_=e;'),'error')
 yield Case('error/enum-to-integer',program('const E=enum(u8){a=1,b=7,c=250,};','const n:u8=E.b;_=n;'),'error')
 yield Case('error/missing-literal',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=.missing;_=e;'),'error')
 yield Case('error/missing-type-field',program('const E=enum(u8){a=1,b=7,c=250,};','_=E.missing;'),'error')
 yield Case('error/missing-builtin-field',program('const E=enum(u8){a=1,b=7,c=250,};','_=@field(E,"missing");'),'error')
 yield Case('error/known-hole',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@enumFromInt(2);_=e;'),'error')
 yield Case('error/known-width',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@enumFromInt(257);_=e;'),'error')
 yield Case('error/known-negative',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@enumFromInt(-1);_=e;'),'error')
 yield Case('error/known-undefined',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@enumFromInt(@as(u8,undefined));_=e;'),'error')
 yield Case('error/from-noninteger',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=@enumFromInt(true);_=e;'),'error')
 yield Case('error/from-no-context',program('const E=enum(u8){a=1,b=7,c=250,};','_=@enumFromInt(7);'),'error')
 yield Case('error/from-wrong-context',program('','const n:u8=@enumFromInt(1);_=n;'),'error')
 yield Case('error/intFrom-literal',program('','_=@intFromEnum(.a);'),'error')
 yield Case('error/intFrom-integer',program('','_=@intFromEnum(@as(u8,1));'),'error')
 yield Case('error/duplicate-tags',program('const E=enum(u8){a=7,b=7,};','_=@sizeOf(E);'),'error')
 yield Case('error/duplicate-names',program('const E=enum{a,a,};','_=@sizeOf(E);'),'error')
 yield Case('error/valued-inferred',program('const E=enum{a=7,b,};','_=@sizeOf(E);'),'error')
 yield Case('error/implicit-overflow',program('const E=enum(u1){a,b,c,};','_=@sizeOf(E);'),'error')
 yield Case('error/explicit-overflow',program('const E=enum(u8){a=256,b,};','_=@sizeOf(E);'),'error')
 yield Case('error/negative-tag',program('const E=enum(u8){a=-1,b,};','_=@sizeOf(E);'),'error')
 yield Case('error/noninteger-backing',program('const E=enum(bool){a,b,};','_=@sizeOf(E);'),'error')
 yield Case('error/empty-size',program('const E=enum{};','_=@sizeOf(E);'),'error')
 yield Case('error/empty-align',program('const E=enum{};','_=@alignOf(E);'),'error')
 yield Case('error/empty-explicit-integer',program('const E=enum(u8){};','_=@sizeOf(E);'),'error')
 yield Case('error/const-mutation',program('const E=enum(u8){a=1,b=7,c=250,};','const e:E=.a;e=.b;'),'error')
 yield Case('error/wrong-argument-nominal',program('const E=enum(u8){a=1,b=7,c=250,};const F=enum(u8){a=1,b=7,c=250,};fn f(e:E)void{_=e;}','f(F.a);'),'error')
 yield Case('error/wrong-argument-count',program('const E=enum(u8){a=1,b=7,c=250,};fn f(e:E)void{_=e;}','f();'),'error')
 yield Case('error/struct-default-wrong',program('const E=enum(u8){a=1,b=7,c=250,};const F=enum{a,b,};const H=struct{e:E=F.a,};','const h:H=.{};_=h;'),'error')
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('szc');p.add_argument('zig');p.add_argument('--reference-only',action='store_true');p.add_argument('--report',type=Path);args=p.parse_args();records=[];failures=[];all_cases=list(cases())
 if not len(all_cases)<=90:p.error('90 case bound exceeded')
 with tempfile.TemporaryDirectory(prefix='szc-enum-')as directory:
  path=Path(directory)/'test.zig'
  for index,case in enumerate(all_cases,1):
   path.write_text(case.source)
   if not args.reference_only:a=run_compiler([args.szc,SZC_MODE,str(path)],case.source,f'diff_enum case {index} szc',timeout=120)
   b=run_compiler([args.zig,'build-exe',str(path),'-fno-emit-bin','-j2'],case.source,f'diff_enum case {index} zig',timeout=120)
   error=primary_error(b.stderr);records.append(dict(index=index,label=case.label,lane=case.lane,source=case.source,zig_status=b.returncode,zig_error=error,zig_stderr=b.stderr.decode(errors='replace')))
   if args.reference_only and (b.returncode!=(case.lane=='error')or(case.lane=='error'and error is None)):failures.append('reference assumption failed: '+case.label+'\n'+b.stderr.decode(errors='replace'))
   if not args.reference_only and (a.returncode!=b.returncode or primary_error(a.stderr)!=error):failures.append('disagreement: '+case.label+'\n'+case.source+'\n'+a.stderr.decode(errors='replace')+b.stderr.decode(errors='replace'))
   if args.report:args.report.write_text(json.dumps(records,indent=2)+'\n')
 print(f'enums: {len(records)} cases; {sum(r["zig_status"]!=0 for r in records)} reference primary errors; {len(failures)} failures')
 if failures:raise SystemExit('\n'.join(failures))
if __name__=='__main__':main()
